// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;
    function setUp() public { c = new Product(); }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != caller2);
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));
        vm.assume(!_isPrecompile(caller1) && !_isPrecompile(caller2));
        vm.assume(caller1.code.length == 0 && caller2.code.length == 0);

        vm.prank(caller1);
        (bool ok1, bytes memory data1) = address(c).call(abi.encodeWithSignature("controller()"));
        vm.prank(caller2);
        (bool ok2, bytes memory data2) = address(c).call(abi.encodeWithSignature("controller()"));

        assertTrue(ok1 && ok2 && keccak256(data1) == keccak256(data2));
    }

    function _isPrecompile(address a) internal view returns (bool) {
        return a.code.length > 0 && a.balance == 0;
    }
}
